9	import { useEffect, useMemo, useState } from "react";
10	import Link from "next/link";
11	import { getRequirementDetail, type Evidence, type RequirementDetail } from "@/src/lib/api";
12	import { RequirementDetailView } from "@/src/components/RequirementDetailView";
13	
14	export function RequirementDetailPageClient({ id }: { id: string }) {
15	  const [detail, setDetail] = useState<RequirementDetail | null>(null);
16	  const [error, setError] = useState<string | null>(null);
17	  const [isLoading, setIsLoading] = useState(true);
18	
19	  useEffect(() => {
20	    let cancelled = false;
21	    (async () => {
22	      setIsLoading(true);
23	      setError(null);
24	      try {
25	        const loaded = await getRequirementDetail(id);
26	        if (!cancelled) setDetail(loaded);
27	      } catch (err) {
28	        if (!cancelled) setError((err as Error).message);
29	      } finally {
30	        if (!cancelled) setIsLoading(false);
31	      }
32	    })();
33	    return () => {
34	      cancelled = true;
35	    };
36	  }, [id]);
37	
38	  // Belege je Befund vorsortieren, damit die Karten nicht bei jedem Render neu filtern.
39	  const evidenceBySignal = useMemo(() => {
40	    const byId = new Map<string, Evidence>();
41	    for (const item of detail?.evidence ?? []) byId.set(item.id, item);
42	    const bySignal = new Map<string, Evidence[]>();
43	    for (const signal of detail?.signals ?? []) {
44	      bySignal.set(
45	        signal.id,
46	        signal.evidence_ids.map((evId) => byId.get(evId)).filter((e): e is Evidence => Boolean(e)),
47	      );
48	    }
49	    return bySignal;
50	  }, [detail]);
51	
52	  return (
53	    <div className="min-h-screen">
54	      <main className="mx-auto max-w-5xl px-6 py-8">
55	        <Link href="/" className="text-sm text-blue-600 hover:underline dark:text-blue-400">
56	          ← Back to list
57	        </Link>
58	
59	        {error && (
60	          <div className="mt-4 rounded-md border border-rose-300 bg-rose-50 px-4 py-3 text-sm text-rose-800 dark:border-rose-800 dark:bg-rose-950 dark:text-rose-300">
61	            {error}
62	          </div>
63	        )}
64	        {!error && isLoading && <p className="mt-4 text-sm text-zinc-500 dark:text-zinc-400">Loading…</p>}
65	
66	        {!error && !isLoading && detail && (
67	          <>
68	            <RequirementDetailView detail={detail} evidenceBySignal={evidenceBySignal} />
69	            <div className="mt-8">
70	              <Link href="/" className="text-sm text-blue-600 hover:underline dark:text-blue-400">
71	                ← Back to list
72	              </Link>
